-- KPD V2 English website copy — consolidated CMS migration.
-- Source of truth: 162026 KPD - Website Copy (E) V2.docx
--
-- This is the only V2 content migration to apply. It supersedes the earlier
-- partial home/global, legal-page and legacy-module scripts. It changes CMS
-- copy only; it does not change schema, routes, CSS, images, or behaviour.
-- It is idempotent and intentionally preserves project media already in use.

BEGIN;

-- 1. Backup (safe to re-run: only created once).
CREATE TABLE IF NOT EXISTS project_modules_backup_20261009 AS SELECT * FROM project_modules WHERE false;
CREATE TABLE IF NOT EXISTS projects_backup_20261009 AS SELECT * FROM projects WHERE false;
INSERT INTO project_modules_backup_20261009 SELECT * FROM project_modules WHERE "projectId" IN (SELECT id FROM projects WHERE slug IN ('seven-x-seven', 'emerald-villa', 'dubai-hills-mansion')) AND NOT EXISTS (SELECT 1 FROM project_modules_backup_20261009);
INSERT INTO projects_backup_20261009 SELECT * FROM projects WHERE slug IN ('seven-x-seven', 'emerald-villa', 'dubai-hills-mansion') AND NOT EXISTS (SELECT 1 FROM projects_backup_20261009);

UPDATE projects
SET name = CASE slug
  WHEN 'seven-x-seven' THEN 'seven x seven Meydan Horizon Residences'
  WHEN 'emerald-villa' THEN 'Villa 174'
  WHEN 'dubai-hills-mansion' THEN 'Villa 24'
END,
"updatedAt" = NOW()
WHERE slug IN ('seven-x-seven', 'emerald-villa', 'dubai-hills-mansion');

-- seven-x-seven ----------------------------------------------------------------
UPDATE projects SET tagline = 'Luxury, in balance.', description = 'The freedom to have both. City and sanctuary. Privacy and connection. Stillness and play. The first residential expression of seven x seven, shaped by Japanese thinking and made for the way Dubai lives.', "updatedAt" = NOW() WHERE slug = 'seven-x-seven';
INSERT INTO project_modules ("id", "projectId", "slug", "title", "kind", "profile", "content", "sortOrder", "updatedAt")
VALUES ('mod_' || substr(md5(random()::text || clock_timestamp()::text), 1, 22), (SELECT id FROM projects WHERE slug = 'seven-x-seven'), 'meydan-horizon', 'In Dubai. In balance.', 'CUSTOM'::"ModuleKind", 'FULL', $json${"text":"Meydan Horizon places city access and natural sanctuary in the same frame. Downtown, DIFC, DXB and Ras Al Khor remain within practical reach, while views open towards Creek Harbour, Burj Khalifa and Meydan Racecourse.","images":["/legacy/assets/images/single-project/pdf/seven-x-seven-first-fold.jpg"],"items":[{"value":"10 min","label":"Ras Al Khor"},{"value":"10 min","label":"Downtown Dubai"},{"value":"10 min","label":"DXB Airport"}]}$json$::jsonb, 10, NOW())
