VALUES ('mod_' || substr(md5(random()::text || clock_timestamp()::text), 1, 22), (SELECT id FROM projects WHERE slug = 'dubai-hills-mansion'), 'floor-plans', 'Floor Plans', 'FLOOR_PLAN'::"ModuleKind", 'FULL', $json${"text":"Indicative layouts organise arrival, entertaining, family privacy, guest accommodation and outdoor living with clarity.","items":[{"label":"Type A","image":"/legacy/assets/images/floor-plans/seven-x-seven-type-a.svg","url":"/legacy/contact.html?project=Villa%2024&request=floor-plan-a"},{"label":"Type B","image":"/legacy/assets/images/floor-plans/seven-x-seven-type-b.svg","url":"/legacy/contact.html?project=Villa%2024&request=floor-plan-b"},{"label":"Type C","image":"/legacy/assets/images/floor-plans/seven-x-seven-type-c.svg","url":"/legacy/contact.html?project=Villa%2024&request=floor-plan-c"}]}$json$::jsonb, 50, NOW())
ON CONFLICT ("projectId", "slug") DO UPDATE SET "title" = EXCLUDED."title", "kind" = EXCLUDED."kind", "content" = project_modules."content" || (EXCLUDED."content" - ARRAY['images', 'mapUrl', 'url']), "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = NOW();
INSERT INTO project_modules ("id", "projectId", "slug", "title", "kind", "profile", "content", "sortOrder", "updatedAt")
VALUES ('mod_' || substr(md5(random()::text || clock_timestamp()::text), 1, 22), (SELECT id FROM projects WHERE slug = 'dubai-hills-mansion'), 'payment-plan', 'Payment Plan', 'CUSTOM'::"ModuleKind", 'FULL', $json${"text":"Payment milestones are structured around reservation, construction, handover and optional post-handover settlement. Final terms are confirmed against current availability.","url":"mailto:info@kpd.ae?subject=Villa%2024%20Payment%20Plan","items":[{"value":"15%","label":"On booking","text":"Reservation and initial allocation milestone."},{"value":"35%","label":"During construction","text":"Staged payments aligned to project progress."},{"value":"40%","label":"On completion","text":"Balance due at handover and title transfer."},{"value":"10%","label":"After handover","text":"Optional settlement window subject to offer terms."}]}$json$::jsonb, 60, NOW())
