INSERT INTO site_settings (key, value, "updatedAt") VALUES
('global', $json${"email":"info@kpd.ae","phone":"+971 48 567 891","whatsapp":"https://wa.me/97148567891","website":"https://kpd.com","newsletterNote":"Project updates, market insights and Kasumigaseki Properties Development news. Sent sparingly.","facebook":"https://www.facebook.com/","x":"https://x.com/","instagram":"https://www.instagram.com/","youtube":"https://www.youtube.com/","linkedin":"https://www.linkedin.com/company/kasumigasekimiddleeast"}$json$::jsonb, NOW()),
('home', $json${"introStats":[{"value":"$4.4B","label":"Global AUM"},{"value":"$320M","label":"Dubai Real Estate"},{"value":"$2.27B","label":"Logistics"},{"value":"$1.64B","label":"Hotels"}],"statsNote":"(As of August 2026)","bannerSlides":[{"image":"/legacy/assets/images/project-media/sxs/facade%20left%202.png","label":"seven x seven Meydan Horizon Residences"},{"image":"/legacy/assets/images/project-media/Emerald%20Villa/tm2161_vp29_interior_3brmasterbedroom_rev06.jpg","label":"Villa 174"},{"image":"/legacy/assets/images/library/driveway-of-a-contemporary-house-with-a-garden-are-2026-01-08-00-24-21-utc.jpg","label":"Villa 24"}],"developmentCards":[{"href":"/developments/seven-x-seven","image":"/legacy/assets/images/project-media/sxs/facade%20right%202.png","title":"seven x seven Meydan Horizon Residences","copy":"A composed Meydan Horizon residence where arrival, light and privacy meet measured access to Dubai's core districts."},{"href":"/developments/emerald-villa","image":"/legacy/assets/images/project-media/Emerald%20Villa/37.jpg","title":"Villa 174","copy":"A private family villa organised around planted arrival, layered privacy and room for daily life to unfold."},{"href":"/developments/dubai-hills-mansion","image":"/legacy/assets/images/library/high-rise-apartment-buildings-in-downtown-vancouve-2026-03-20-04-35-07-utc.jpg","title":"Villa 24","copy":"A mansion-scale residence where garden arrival, private wellness and long-horizon family living are composed as one."}],"heroVideo":"/videos/hero-experience-center.mp4","introHeading":"Turning Challenge\\nInto Value","introParagraphs":["As the first Japanese developer in the UAE, Kasumigaseki Properties Development is the development arm of Kasumigaseki Capital, a public Tokyo-listed company. It introduces a distinctive approach to real estate: a promise of a higher standard of life. Driven by a commitment to superior quality, we believe meaningful developments begin with a deep respect for their environment, context, and community.","From refined craftsmanship and forward-thinking innovation to thoughtful guardianship, we uphold rigorous standards at every stage, creating spaces that stand the test of time."],"developmentHeading":"Different places. One standard.","contactHeading":"Visit the Experience Centre","contactText":"Some things are best understood in person. At the Kasumigaseki Properties Development Experience Center you can handle the finishes, walk the model and talk through the project with the people who shaped it."}$json$::jsonb, NOW())
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, "updatedAt" = NOW();

-- Fixed CMS pages ------------------------------------------------------------
INSERT INTO static_pages (id, slug, title, content, status, "updatedAt") VALUES
('page_v2_about','about','About Us',$json$[{"type":"hero","heading":"Built on understanding.","text":"Kasumigaseki Properties Development brings the institutional discipline of Kasumigaseki Capital listed on the Tokyo Stock Exchange Prime Market, externally audited, and publicly held. For investors and residents, this model is built to foster trust, mitigate risk, and support long-term value creation.","image":"/legacy/assets/images/library/about-advisory-model-presentation.jpg"},{"type":"paragraph","text":"KAH-soo-mee-GAH-seh-kee."},{"type":"paragraph","text":"Kasumi means mist. Seki means barrier or gate. The name comes from Tokyo's government district, a place associated with infrastructure, continuity and long-term responsibility."},{"type":"paragraph","text":"We carry that mindset into development. Our Japanese heritage is not an aesthetic layer. It is how we govern, how we decide, how we build and how long we remain accountable for what we create."},{"type":"paragraph","text":"Kasumigaseki Properties Development is the UAE expression of that philosophy: one standard of quality, peace of mind and innovation, applied without exception."},{"type":"paragraph","text":"Behind that philosophy is a global platform spanning development, hospitality, logistics, healthcare and fund management. In the UAE, that breadth is concentrated into a focused development pipeline."},{"type":"about","mission":"The art of knowing.\\n\\nKnowing is our discipline before it is our promise. Every decision is evidenced. It is why our standard repeats without exception, why our care continues long after handover, and why innovation never stops giving. This is the power of Kasumigaseki Properties Development","vision":"Turning challenge into value.\\n\\nAdopted from our parent brand, we are driven by discovery and knowledge: to uncover the opportunity within the landscape, find the possibility in the challenge, and commit to delivering livable solutions. The value we create is intended to last. We look beyond the immediate solution to understand what people and places need, creating outcomes that serve a genuine purpose today while contributing to the long-term vitality of the communities they become part of.","chairmanText":"The markets we operate in reward patience, clarity and disciplined execution. Kasumigaseki Properties Development was formed to bring those qualities into development decisions: from how land is assessed to how a finished place will be lived in, operated and valued over time. Our work is measured by the confidence of our partners, the quality of our delivery and the long-term relevance of the communities and assets we help create.","chairmanName":"Mohammed Alabbar","chairmanRole":"Chairman","chairmanImage":"/legacy/assets/images/team/Alabbar.jpg","management":[{"name":"Tatsuya Suzuki","role":"CEO","bio":"","image":"/team/tatsuya-suzuki.jpg"},{"name":"Hiroyuki Chiba","role":"Executive Director","bio":"","image":""},{"name":"Ammar Al Tamimi","role":"Development Director","bio":"","image":""},{"name":"Anas Al Khatib","role":"Commercial Director","bio":"","image":""}]}]$json$::jsonb,'PUBLISHED'::"ContentStatus",NOW()),
('page_v2_legacy','legacy','History',$json$[{"type":"hero","heading":"History","text":"","image":"/legacy/assets/images/about/about-hero.jpg"},{"type":"legacy","timeline":[{"year":"2011","title":"Formation of Kasumigaseki Capital","summary":"Kasumigaseki Capital was founded in 2011.","body":"","image":"/timeline/2011-kc-formation.jpg"},{"year":"2018","title":"Listing on Tokyo Stock Exchange Mothers Market","summary":"Kasumigaseki Capital marked its transition from a private developer to a publicly listed growth platform with institutional capital access.","body":"","image":"/timeline/2018-tse-mothers.jpg"},{"year":"2020","title":"Launch of fav","summary":"Kasumigaseki Capital completed and launched the first hotel property under fav hotel brand.","body":"","image":"/timeline/2020-fav.jpg"},{"year":"2022","title":"Middle East Market Entry","summary":"Kasumigaseki Capital formally entered the Middle East with the establishment of Kasumigaseki Middle East LLC in Dubai.","body":"","image":"/timeline/2022-kc-mena.jpg"},{"year":"2023","title":"Upgrade to Tokyo Stock Exchange Prime Market","summary":"Kasumigaseki Capital was upgraded to the Tokyo Stock Exchange Prime Market, Japan's highest listing tier.","body":"","image":"/timeline/2023-tse-prime.jpg"},{"year":"2024","title":"Launch of seven x seven","summary":"Kasumigaseki Capital expanded its hospitality portfolio with the launch of seven x seven in Itoshima, Fukuoka and its flagship property in Ishigaki, Okinawa.","body":"","image":"/timeline/2024-seven-x-seven.jpg"},{"year":"2026","title":"Establishment of Kasumigaseki Properties Development","summary":"Kasumigaseki Middle East LLC established Kasumigaseki Properties Development LLC as Kasumigaseki Capital's dedicated UAE development arm.","body":"","image":"/timeline/2026-kpd.jpg"},{"year":"2026","title":"Launch of seven x seven residences in Meydan Horizon","summary":"Kasumigaseki Properties Development’s first flagship residential project in the UAE, comprising 155 residences.\\nThe launch marks seven x seven’s first move from hospitality into residential living.","body":"","image":"/timeline/2026-seven-x-seven-meydan.jpg"}]}]$json$::jsonb,'PUBLISHED'::"ContentStatus",NOW()),
('page_v2_contact','contact','Contact',$json$[{"type":"hero","heading":"Plan a visit.\\nStart a conversation.","text":"Tell us what you are looking for and the right person will respond. Private previews, walkthroughs and advisory conversations are coordinated through the Kasumigaseki Properties Development Experience Center.","image":"/legacy/assets/images/experience-center/hq/10.jpg"}]$json$::jsonb,'PUBLISHED'::"ContentStatus",NOW()),
('page_v2_invest','invest-in-dubai','Invest in Dubai',$json$[{"type":"hero","heading":"Long-horizon value in Dubai","text":"Dubai moves fast. Capital should not. We begin with the facts: regulated ownership, payment structure, location logic, use case and exit plan. Then, we decide what deserves a place in the portfolio. The aim is advisory clarity around a composed residential asset, not speed for its own sake.","image":"/legacy/assets/images/library/view-of-dubai-skyline-including-the-burj-khalifa-2026-03-18-08-25-37-utc.jpg"}]$json$::jsonb,'PUBLISHED'::"ContentStatus",NOW())
ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, content=EXCLUDED.content, status=EXCLUDED.status, "updatedAt"=NOW();

INSERT INTO static_pages (id,slug,title,content,status,"updatedAt") VALUES
('page_v2_terms','terms','Terms of Use',$json$[{"type":"hero","heading":"Terms of Use"},{"type":"paragraph","text":"These terms govern use of the Kasumigaseki Properties Development website and the information presented across project, company, news and contact pages."},{"type":"heading","heading":"Website Information"},{"type":"paragraph","text":"Content is provided for general information only. Project information, images, dimensions, features, prices, timelines and availability may change without notice and should be verified directly with Kasumigaseki Properties Development."},{"type":"heading","heading":"Use of Content"},{"type":"paragraph","text":"Text, images, marks, layouts and design materials are owned by or licensed to Kasumigaseki Properties Development and may not be reproduced or distributed without written permission."},{"type":"heading","heading":"No Investment Advice"},{"type":"paragraph","text":"Nothing on this website should be treated as financial, legal, tax or investment advice. Visitors should obtain independent advice before making decisions."},{"type":"heading","heading":"Contact"},{"type":"paragraph","text":"For questions about these terms, contact info@kpd.ae."}]$json$::jsonb,'PUBLISHED'::"ContentStatus",NOW()),
('page_v2_privacy','privacy-policy','Privacy Policy',$json$[{"type":"hero","heading":"Privacy Policy"},{"type":"paragraph","text":"Kasumigaseki Properties Development respects the privacy of website visitors, buyers, investors, partners and people who contact us through forms, email or events."},{"type":"heading","heading":"Information We Collect"},{"type":"paragraph","text":"We may collect contact details, enquiry preferences, message content, event registrations, newsletter signups and basic website usage data."},{"type":"heading","heading":"How We Use Information"},{"type":"paragraph","text":"Information is used to respond to enquiries, coordinate meetings, share project updates, improve the website experience and maintain appropriate business records."},{"type":"heading","heading":"Sharing"},{"type":"paragraph","text":"We do not sell personal information. We may share data with service providers, advisers or project partners where needed to respond to a request or operate the website."},{"type":"heading","heading":"Your Choices"},{"type":"paragraph","text":"You may request access, correction or deletion of your information by contacting info@kpd.ae."}]$json$::jsonb,'PUBLISHED'::"ContentStatus",NOW()),
('page_v2_cookie','cookie-policy','Cookie Policy',$json$[{"type":"hero","heading":"Cookie Policy"},{"type":"paragraph","text":"This website may use cookies and similar technologies to support basic operation, understand website performance and improve visitor experience."},{"type":"heading","heading":"Types of Cookies"},{"type":"paragraph","text":"Essential cookies support page functionality. Analytics cookies help us understand aggregate browsing behaviour. Preference cookies may remember choices made by visitors."},{"type":"heading","heading":"Managing Cookies"},{"type":"paragraph","text":"You can manage or block cookies through your browser settings. Some parts of the website may not function as intended if cookies are disabled."},{"type":"heading","heading":"Updates"},{"type":"paragraph","text":"We may update this policy from time to time to reflect website or regulatory changes."},{"type":"heading","heading":"Contact"},{"type":"paragraph","text":"Share your questions on info@kpd.ae."}]$json$::jsonb,'PUBLISHED'::"ContentStatus",NOW())
ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, content=EXCLUDED.content, status=EXCLUDED.status, "updatedAt"=NOW();

