-- Seeded editorial records ---------------------------------------------------
UPDATE articles SET title='seven x seven: Luxury, in balance', summary='A sharper urban mixed-use brief built around positioning, movement, and future delivery logic.', body=$json$["seven x seven is shaped around an urban reading of density, frontage, and movement. The project is positioned to make its address, arrival sequence, and residential experience feel coherent from the street to the private interior.","Rather than relying on scale alone, the project uses measured facade rhythm, amenity logic, and material restraint to create a residential experience that is composed and commercially legible.","The development reflects KPD's wider approach: every spatial decision should carry operational, experiential, and long-term value."]$json$::jsonb, "updatedAt"=NOW() WHERE slug='seven-x-seven-project-note';
UPDATE articles SET title='Villa 174 Private Preview', summary='An invitation-only preview of Villa 174’s planning, amenity story, and garden-led residential experience.', body=$json$["Villa 174 was presented through a private preview focused on the relationship between arrival, landscape, privacy, and interior calm. The walkthrough introduced the project as a residential environment shaped for family-scaled living and long-horizon ownership.","The preview highlighted the role of garden rooms, shaded outdoor areas, and warm interior materiality in creating a home that feels generous without becoming performative.","KPD's team framed the project as a quieter expression of luxury: one built around clarity, daily use, and a composed sense of permanence."]$json$::jsonb, "updatedAt"=NOW() WHERE slug='emerald-villa-private-preview';
UPDATE articles SET body=$json$["Every durable project begins before architecture. It starts with land logic: what a site allows, what it resists, how it is approached, and how its edges will be read over time.","Frontage, visibility, service access, arrival rhythm, and surrounding movement patterns all influence the kind of product a site can support. Treating those inputs carefully gives a project its first layer of discipline.","When form follows that logic, the architecture has a clearer job. It does not need to compensate for weak positioning; it can refine a proposition that already understands its place."]$json$::jsonb, "updatedAt"=NOW() WHERE slug='land-logic-before-form';

-- 2. Check before committing: every project should list its delivered modules.
SELECT p.slug AS project, m.slug AS module, m."sortOrder" FROM project_modules m JOIN projects p ON p.id = m."projectId" WHERE p.slug IN ('seven-x-seven', 'emerald-villa', 'dubai-hills-mansion') ORDER BY p.slug, m."sortOrder";

